-- Feature 26: local synthetic schedule-sync fixture history; not a scheduler integration.
CREATE TABLE IF NOT EXISTS schedule_sync_scopes (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),UNIQUE(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS schedule_sync_desired_states (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES schedule_sync_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS schedule_sync_material_decisions (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES schedule_sync_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS schedule_sync_commands (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash text NOT NULL,profile_revision integer NOT NULL CHECK(profile_revision>0),desired_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),UNIQUE(operator_test_id,scope_hash,profile_revision),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES schedule_sync_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS schedule_sync_transitions (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,command_hash text NOT NULL,sequence integer NOT NULL CHECK(sequence>0),payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),UNIQUE(operator_test_id,scope_hash,command_hash,sequence),FOREIGN KEY(operator_test_id,scope_hash,command_hash) REFERENCES schedule_sync_commands(operator_test_id,scope_hash,artifact_hash));
CREATE TABLE IF NOT EXISTS schedule_sync_actual_observations (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES schedule_sync_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS schedule_sync_roots (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES schedule_sync_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS schedule_sync_request_claims (operator_test_id text NOT NULL,idempotency_key text NOT NULL,request_hash char(64) NOT NULL,root_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,idempotency_key));
CREATE OR REPLACE FUNCTION schedule_sync_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'schedule_sync_append_only'; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY(SELECT table_name FROM information_schema.tables WHERE table_schema=current_schema() AND table_name LIKE 'schedule_sync_%') LOOP EXECUTE format('DROP TRIGGER IF EXISTS schedule_sync_no_mutation ON %I',t); EXECUTE format('CREATE TRIGGER schedule_sync_no_mutation BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION schedule_sync_append_only()',t); END LOOP; END $$;
